mapper.select:
select f.module_id as moduleId, f.module_table_id as moduleTableId, m.table_alias as moduleTableAlias, f.relation_module_table_id as relationMoudleTableId, m1.table_alias as relationMoudleAlias, f.relation_direction as relationDirection, f.field_id as fieldId, c.column_name as fieldName, c1.column_name as relationFieldName, f.relation_field_id as relationFieldId from cfg_module_relation_field f left join cfg_module_table m on f.module_table_id = m.id and m.deleted=0 left join cfg_module_table m1 on f.relation_module_table_id = m1.id and m1.deleted=0 left join cfg_column_definition c on m.table_id = c.table_id and f.field_id= c.id and c.deleted=0 left join cfg_column_definition c1 on m1.table_id = c1.table_id and f.relation_field_id= c1.id and c1.deleted=0 where f.deleted=0
and f.module_id = #{moduleId}
ORDER BY m.table_alias
